-- SQL*Plus SHOW command.
-- https://docs.oracle.com/en/database/oracle/oracle-database/26/sqpug/SHOW.html
SHOW ERRORS;

SHO ERR;

SHOW ERRORS FUNCTION my_func;

SHOW ERRORS PACKAGE BODY my_schema.my_pkg;

SHOW ERRORS JAVA CLASS my_class;

SHO ERRORS PROCEDURE my_proc;

SHOW ERR TRIGGER my_trigger;

SHOW ERRORS VIEW my_view;

SHOW ERRORS DIMENSION my_dimension;

SHOW ERRORS TYPE my_type;

SHOW ERRORS TYPE BODY my_type;

SHOW ERRORS PACKAGE my_pkg;

SHOW ERRORS ANALYTIC VIEW my_av;

SHOW ERRORS ATTRIBUTE DIMENSION my_ad;

SHOW ERRORS HIERARCHY my_hier;

SHOW PARAMETER;

SHOW PARAMETERS sga_target;

SHOW SPPARAMETER;

SHOW SPPARAMETERS open_cursors;

SHOW RECYCLEBIN;

SHOW RECYCLEBIN my_table;

SHOW CONNECTION NETSERVICENAMES;

SHOW CONN NETS orcl1 orcl2;

SHOW ALL;

SHOW USER;

SHOW SGA;

SHOW PDBS;

SHOW EDITION;

SHOW RELEASE;

SHOW REL;

SHOW BTITLE;

SHOW TTITLE;

SHOW SPOOL;

SHOW STATEMENTCACHE;

SHOW SQLCODE;

SHOW LINESIZE;

SHOW CON_NAME;

show errors
